    IN_INSPECTION,       // 검수 중
    FAILED_INSPECTION,   // 검수 불합격
    IN_STORAGE,          // 창고 보관 중
    ON_AUCTION,          // 판매 입찰 중
    SELLING,             // 판매중 (등록된 상태)
    SOLD,                // 판매 완료
